<?php
// Description: Public menu page displaying cafe items with filtering, ratings, and feedback system.
// Function: Shows menu items from database, handles customer feedback submission, displays ratings.
// Technical: Uses MySQLi for database queries, PHP for server-side logic, JavaScript for client-side interactions.

// Database connection
// Description: Includes the database configuration file.
// Function: Establishes database connection for menu and feedback queries.
// Technical: Requires db.php to be in same directory; $conn becomes available globally.
include 'db.php';

// Handle feedback submission
// Description: Processes customer feedback form submissions.
// Function: Validates and inserts feedback data into database, shows success message.
// Technical: POST method check, prepared statements for security, input sanitization with trim().
if ($_SERVER["REQUEST_METHOD"] === "POST" && isset($_POST['submit_feedback'])) {
    $item_id = intval($_POST['item_id'] ?? 0);
    $rating = intval($_POST['rating'] ?? 0);
    $comment = trim($_POST['comment'] ?? '');
    $customer_name = trim($_POST['customer_name'] ?? 'Anonymous');
    
    // Description: Validates feedback input data.
    // Function: Ensures item ID is valid and rating is within 1-5 range.
    // Technical: Type casting with intval, range validation for rating.
    if ($item_id > 0 && $rating >= 1 && $rating <= 5) {
        $stmt = $conn->prepare("INSERT INTO feedback (menu_item_id, customer_name, rating, comment) VALUES (?, ?, ?, ?)");
        $stmt->bind_param("isis", $item_id, $customer_name, $rating, $comment);
        $stmt->execute();
        $stmt->close();
        $feedback_success = "Thank you for your feedback!";
    }
}

// Get average ratings for items
// Description: Retrieves average ratings and review counts for all menu items.
// Function: Calculates aggregated feedback data for display on menu cards.
// Technical: GROUP BY query for aggregation, associative array for quick lookup by item ID.
$ratings_query = $conn->query("
    SELECT menu_item_id, AVG(rating) as avg_rating, COUNT(*) as review_count 
    FROM feedback 
    GROUP BY menu_item_id
");
$item_ratings = [];
while ($r = $ratings_query->fetch_assoc()) {
    $item_ratings[$r['menu_item_id']] = $r;
}
