<!-- Description: JavaScript for category filtering, chatbot, and feedback modal functionality.
Function: Handles user interactions for filtering menu items, AI chatbot responses, and feedback submission.
Technical: Event listeners, DOM manipulation, AJAX-like message handling. -->
<script>
// --- Category filter (pure JS, no reload) ---
// Description: Handles category filter button clicks.
// Function: Shows/hides menu items based on selected category with smooth transitions.
// Technical: Event listeners on filter buttons, CSS transitions for animations.
document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', function() {
        document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        this.classList.add('active');

        const filter = this.dataset.filter;
        document.querySelectorAll('.menu-card').forEach(card => {
            const show = filter === 'all' || card.dataset.category === filter;
            card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
            if (show) {
                card.style.opacity = '1'; card.style.transform = '';
                card.style.display = 'flex';
            } else {
                card.style.opacity = '0'; card.style.transform = 'scale(0.95)';
                setTimeout(() => { if(card.dataset.category !== filter && filter !== 'all') card.style.display = 'none'; }, 300);
            }
        });
    });
});

// --- Feedback Modal ---
// Description: Global variable for current star rating.
// Function: Tracks the selected rating value.
// Technical: Number variable updated by user interactions.
let currentRating = 0;

// Description: Opens the feedback modal for a specific item.
// Function: Displays modal with item details and resets rating.
// Technical: DOM manipulation to show modal and set form values.
function openFeedback(itemId, itemName) {
    document.getElementById('feedbackItemId').value = itemId;
    document.getElementById('feedbackItemName').textContent = 'Rating: ' + itemName;
    document.getElementById('feedbackModal').style.display = 'flex';
    currentRating = 0;
    updateStars();
}

// Description: Closes the feedback modal.
// Function: Hides the modal dialog.
// Technical: DOM style manipulation to hide element.
function closeFeedback() {
    document.getElementById('feedbackModal').style.display = 'none';
}

// Description: Sets the star rating value.
// Function: Updates current rating and visual star display.
// Technical: Variable assignment and DOM updates.
function setRating(rating) {
    currentRating = rating;
    updateStars();
    // Update hidden radio
    document.querySelector(`input[name="rating"][value="${rating}"]`).checked = true;
}

// Description: Updates star visual display based on current rating.
// Function: Changes star characters and classes for selected rating.
// Technical: DOM query and class manipulation for star elements.
function updateStars() {
    document.querySelectorAll('.star-rating').forEach((star, index) => {
        if (index < currentRating) {
            star.textContent = '★';
            star.classList.add('active');
        } else {
            star.textContent = '☆';
            star.classList.remove('active');
        }
    });
}

// Close modal on outside click
// Description: Event listener for closing modal on background click.
// Function: Closes modal when clicking outside the content area.
// Technical: Event listener on modal element, target checking.
document.getElementById('feedbackModal').addEventListener('click', function(e) {
    if (e.target === this) closeFeedback();
});
</script>

